import { readFile, writeFile } from "node:fs/promises";
import { resolve } from "node:path";

const marker = "// @transport-release-signing";
const defaultBuildFile = resolve("android/app/build.gradle");

export function releaseConfigurationBlock() {
  return `${marker}
// This is appended after Expo prebuild by a version-controlled script. It runs
// during Gradle configuration, before React Native reads Android variants.
// Release tasks must never silently use the debug keystore generated by React
// Native.
def transportReleaseVersionCode = (findProperty('VUNA_TRANSPORT_VERSION_CODE') ?: android.defaultConfig.versionCode.toString()).toInteger()
if (transportReleaseVersionCode <= 0) {
    throw new GradleException('VUNA_TRANSPORT_VERSION_CODE must be a positive integer.')
}
def transportReleaseVersionName = findProperty('VUNA_TRANSPORT_VERSION_NAME') ?: android.defaultConfig.versionName
def transportReleaseStoreFile = findProperty('VUNA_TRANSPORT_RELEASE_STORE_FILE') ?: System.getenv('VUNA_TRANSPORT_RELEASE_STORE_FILE')
def transportReleaseStorePassword = findProperty('VUNA_TRANSPORT_RELEASE_STORE_PASSWORD') ?: System.getenv('VUNA_TRANSPORT_RELEASE_STORE_PASSWORD')
def transportReleaseKeyAlias = findProperty('VUNA_TRANSPORT_RELEASE_KEY_ALIAS') ?: System.getenv('VUNA_TRANSPORT_RELEASE_KEY_ALIAS')
def transportReleaseKeyPassword = findProperty('VUNA_TRANSPORT_RELEASE_KEY_PASSWORD') ?: System.getenv('VUNA_TRANSPORT_RELEASE_KEY_PASSWORD')
def transportHasReleaseSigning = [transportReleaseStoreFile, transportReleaseStorePassword, transportReleaseKeyAlias, transportReleaseKeyPassword].every { it }
def transportReleaseTaskRequested = gradle.startParameter.taskNames.any { it.toLowerCase().contains('release') }
if (transportReleaseTaskRequested && (!findProperty('VUNA_TRANSPORT_VERSION_CODE') || !findProperty('VUNA_TRANSPORT_VERSION_NAME'))) {
    throw new GradleException('Use scripts/build-release-apk.sh to supply the semantic release version.')
}
if (transportReleaseTaskRequested && !transportHasReleaseSigning) {
    throw new GradleException('Release signing is required. Provide VUNA_TRANSPORT_RELEASE_STORE_FILE, VUNA_TRANSPORT_RELEASE_STORE_PASSWORD, VUNA_TRANSPORT_RELEASE_KEY_ALIAS, and VUNA_TRANSPORT_RELEASE_KEY_PASSWORD.')
}
// Do not defer this configuration: React Native reads versionCode while
// configuring variants, and Gradle 9 rejects mutations made afterwards.
android.defaultConfig.versionCode = transportReleaseVersionCode
android.defaultConfig.versionName = transportReleaseVersionName
android.defaultConfig.ndk {
    // Production Vuna Transport is distributed to physical ARM64 Android devices.
    // The CI workflow separately passes this to React Native so it does not
    // compile x86/x86_64 libraries only to discard them from the APK.
    abiFilters 'arm64-v8a'
}
def transportReleaseSigning = android.signingConfigs.maybeCreate('release')
transportReleaseSigning.storeFile = file(transportReleaseStoreFile ?: 'missing-release-keystore')
transportReleaseSigning.storePassword = transportReleaseStorePassword
transportReleaseSigning.keyAlias = transportReleaseKeyAlias
transportReleaseSigning.keyPassword = transportReleaseKeyPassword
android.buildTypes.getByName('release').signingConfig = transportReleaseSigning
`;
}

export async function prepareAndroidRelease(buildFile = defaultBuildFile) {
  const source = await readFile(buildFile, "utf8");
  const desired = `${source.split(marker)[0].trimEnd()}\n\n${releaseConfigurationBlock()}`;
  if (source === desired) return false;
  await writeFile(buildFile, desired);
  return true;
}

if (process.argv[1] === new URL(import.meta.url).pathname) {
  const buildFile = process.argv[2] ? resolve(process.argv[2]) : defaultBuildFile;
  const changed = await prepareAndroidRelease(buildFile);
  console.log(`${changed ? "Prepared" : "Already prepared"} Android release configuration: ${buildFile}`);
}
